script:
@import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,300..600;1,9..144,300..600&display=swap');

html { scroll-behavior: smooth; color-scheme: dark; background: #141110; }
::selection { background: #E2571B; color: #141110; }

/* reveal on scroll: armed by ember_motion only when motion is allowed */
html.em-js .em-rise { opacity: 0; transform: translateY(26px); }
html.em-js .em-rise.em-in {
  opacity: 1; transform: none;
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.9s cubic-bezier(0.22, 1, 0.36, 1);
}
html.em-js .em-d2.em-in { transition-delay: 0.1s; }
html.em-js .em-d3.em-in { transition-delay: 0.2s; }
html.em-js .em-d4.em-in { transition-delay: 0.3s; }

@media (prefers-reduced-motion: no-preference) {
  .em-kb { animation: em-kb 14s cubic-bezier(0.25, 0.46, 0.45, 0.94) both; }
  @keyframes em-kb { from { transform: scale(1.12); } to { transform: scale(1); } }
  .em-pulse { animation: em-pulse 2.4s ease-in-out infinite; }
  @keyframes em-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
  .em-marquee-track { animation: em-marquee 38s linear infinite; }
  .em-marquee:hover .em-marquee-track { animation-play-state: paused; }
  @keyframes em-marquee { to { transform: translateX(-50%); } }
  /* micro parallax, only where scroll-driven animations exist */
  @supports ((animation-timeline: view()) and (animation-range: entry)) {
    .em-drift { animation: em-drift linear both; animation-timeline: view(); }
    @keyframes em-drift { from { transform: translateY(-4%); } to { transform: translateY(4%); } }
  }
}

.em-zoom img { transition: transform 1.2s cubic-bezier(0.22, 1, 0.36, 1); }
.em-zoom:hover img { transform: scale(1.045); }
.em-lift { transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1), border-color 0.5s ease; }
.em-lift:hover { transform: translateY(-6px); border-color: rgba(226, 87, 27, 0.4); }
.em-btn { transition: background-color 0.25s ease, transform 0.35s cubic-bezier(0.22, 1, 0.36, 1); }
.em-btn:hover { background-color: #F2743C; transform: translateY(-2px); }
.em-btn-ghost { transition: border-color 0.25s ease, color 0.25s ease; }
.em-btn-ghost:hover { border-color: #E2571B; color: #E2571B; }
.em-btn-flame-ghost { transition: background-color 0.25s ease, color 0.25s ease; }
.em-btn-flame-ghost:hover { background-color: #E2571B; color: #16100C; }
.em-ul {
  background-image: linear-gradient(currentColor, currentColor);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 1px;
  transition: background-size 0.45s cubic-bezier(0.22, 1, 0.36, 1);
}
.em-ul:hover { background-size: 100% 1px; }
.em-cta .em-arrow { transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1); }
.em-cta:hover .em-arrow { transform: translateX(5px); }
.em-snap { scroll-snap-type: x mandatory; scrollbar-width: none; }
.em-snap::-webkit-scrollbar { display: none; }
.em-snap > * { scroll-snap-align: start; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}
